const dataNode = document.querySelector("#pattern-lens-data");
const root = document.querySelector("[data-pattern-lens]");

if (dataNode && root) {
  const payload = JSON.parse(dataNode.textContent);
  const { locale, copy } = payload;
  // A tiny featured set ships with the page so first paint stays immediate.
  // On the first real interaction Lens upgrades to the larger curated public
  // catalogue generated by the build. It never downloads the full corpus here.
  let patterns = Array.isArray(payload.catalogue) ? payload.catalogue : [];
  let cataloguePromise = null;
  const text = root.querySelector("[data-lens-text]");
  const form = root.querySelector("[data-lens-form]");
  const results = root.querySelector("[data-lens-results]");
  const annotation = root.querySelector("[data-lens-annotation]");
  const empty = root.querySelector("[data-lens-empty]");
  const ready = root.querySelector("[data-lens-ready]");
  const languageButtons = [...root.querySelectorAll("[data-lens-language]")];
  const sampleButtons = [...document.querySelectorAll("[data-lens-sample]")];
  let language = "en";
  let reasoningRules = null;

  const validCataloguePattern = (pattern) => Boolean(
    pattern
    && typeof pattern.id === "string"
    && pattern.id
    && Array.isArray(pattern.langs)
    && pattern.langs.some((item) => item && typeof item.lang === "string" && typeof item.formula === "string" && typeof item.example === "string")
  );

  const loadPatterns = async () => {
    if (cataloguePromise) return cataloguePromise;
    cataloguePromise = fetch("/data/pattern-lens-patterns.json")
      .then((response) => response.ok ? response.json() : null)
      .then((catalogue) => {
        if (!Array.isArray(catalogue)) return patterns;
        const valid = catalogue.filter(validCataloguePattern);
        if (valid.length > patterns.length) patterns = valid;
        return patterns;
      })
      .catch(() => patterns);
    return cataloguePromise;
  };

  const normalize = (value = "") => String(value)
    .replaceAll("**", "")
    .replace(/[’‘]/g, "'")
    .replaceAll(/\s+/g, " ")
    .trim()
    .toLocaleLowerCase();

  const escapeHtml = (value = "") => String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");

  const isMetalinguistic = (input) => {
    const config = reasoningRules?.meta_cues?.[language];
    if (!config) return false;
    try {
      return new RegExp(config.pattern, config.flags).test(input);
    } catch {
      return false;
    }
  };

  const literalSegments = (formula = "") => {
    const stop = new Set(reasoningRules?.stop_segments || []);
    return String(formula)
      .replaceAll("**", "")
      .split(/\[[^\]]+\]|\{[^}]+\}|<[^>]+>/g)
      .flatMap((part) => part.split(/\s+(?:\+|\/|\|)\s+|\s*→\s*/g))
      .map((part) => part
        .replace(/^[\s,;:.!?()\-–—+/|]+|[\s,;:.!?()\-–—+/|]+$/g, "")
        .replaceAll(/\s+/g, " ")
        .trim())
      .filter((part) => {
        const normalized = normalize(part);
        return normalized && !stop.has(normalized) && /[\p{L}\p{N}]/u.test(normalized);
      });
  };

  const recordFor = (pattern) => pattern.langs.find((item) => item.lang === language);
  const strengthRank = (strength) => reasoningRules?.strength_rank?.[strength] || ({ direct: 3, supported: 2, prompt: 1 }[strength] || 0);
  const reasoningScore = (strength) => ({ direct: 18, supported: 16, prompt: 14 }[strength] || 0);
  const strengthLabel = (strength) => {
    if (locale === "ru") return strength === "direct" ? "прямой" : strength === "prompt" ? "задача" : "поддержанный";
    return strength === "direct" ? "direct" : strength === "prompt" ? "prompt" : "supported";
  };

  const classifyReasoning = (input) => {
    if (!reasoningRules?.rules?.length || isMetalinguistic(input)) return [];
    const matches = reasoningRules.rules
      .filter((item) => {
        if (item.language !== language) return false;
        try {
          return new RegExp(item.pattern, item.flags).test(input);
        } catch {
          return false;
        }
      })
      .sort((a, b) => strengthRank(b.strength) - strengthRank(a.strength) || b.priority - a.priority || a.id.localeCompare(b.id));

    const selected = [];
    const seenPatterns = new Set();
    const maxLinks = reasoningRules.max_links_per_sentence || 3;
    for (const item of matches) {
      if (seenPatterns.has(item.pattern_id)) continue;
      seenPatterns.add(item.pattern_id);
      selected.push(item);
      if (selected.length >= maxLinks) break;
    }
    return selected;
  };

  const hasStrongLiteralEvidence = (hits, exampleMatch) => {
    if (exampleMatch || hits.length >= 2) return true;
    return hits.some((segment) => {
      const normalized = normalize(segment);
      return normalized.split(/\s+/).filter(Boolean).length >= 2 && normalized.length >= 8;
    });
  };

  const rank = (input) => {
    const normalizedText = normalize(input);
    if (!normalizedText || isMetalinguistic(input)) return [];
    const reasoningByPattern = new Map(classifyReasoning(input).map((item) => [item.pattern_id, item]));
    return patterns
      .map((pattern) => {
        const lang = recordFor(pattern);
        if (!lang) return null;
        const segments = literalSegments(lang.formula);
        const hits = segments.filter((segment) => normalizedText.includes(normalize(segment)));
        const examples = [lang.example, ...(lang.examples || []).map((item) => item.text)].filter(Boolean);
        const exampleMatch = examples.some((example) => {
          const normalized = normalize(example);
          return normalized.length >= 8 && (normalizedText.includes(normalized) || normalized.includes(normalizedText));
        });
        const reasoningMatch = reasoningByPattern.get(pattern.id) || null;
        if (!reasoningMatch && !hasStrongLiteralEvidence(hits, exampleMatch)) return null;
        const literalScore = hits.reduce((sum, segment) => sum + 2 + Math.min(3, normalize(segment).length / 10), 0)
          + (exampleMatch ? 10 : 0)
          + (hits.length > 1 ? 2 : 0);
        const cueScore = reasoningMatch ? reasoningScore(reasoningMatch.strength) : 0;
        const combinedBonus = reasoningMatch && hits.length ? 3 : 0;
        const score = literalScore + cueScore + combinedBonus;
        if (!score) return null;
        return {
          pattern,
          lang,
          hits,
          reasoningMatch,
          score,
          evidenceType: reasoningMatch && hits.length ? "literal+reasoning" : reasoningMatch ? "reasoning" : "literal",
          coverage: segments.length ? hits.length / segments.length : 0,
        };
      })
      .filter(Boolean)
      .sort((a, b) => b.score - a.score || b.coverage - a.coverage || a.pattern.id.localeCompare(b.pattern.id))
      .slice(0, 6);
  };

  const highlight = (input, hits) => {
    if (!hits.length) return `<p class="lens-annotated-sentence">${escapeHtml(input)}</p>`;
    const ordered = [...hits].sort((a, b) => b.length - a.length);
    const ranges = [];
    const lower = input.toLocaleLowerCase();
    for (const hit of ordered) {
      const needle = hit.toLocaleLowerCase();
      let from = 0;
      while (from < lower.length) {
        const index = lower.indexOf(needle, from);
        if (index < 0) break;
        const end = index + needle.length;
        if (!ranges.some((range) => index < range.end && end > range.start)) ranges.push({ start: index, end });
        from = end;
      }
    }
    ranges.sort((a, b) => a.start - b.start);
    if (!ranges.length) return `<p class="lens-annotated-sentence">${escapeHtml(input)}</p>`;
    let cursor = 0;
    let html = "";
    for (const range of ranges) {
      html += escapeHtml(input.slice(cursor, range.start));
      html += `<span class="lens-hit"><small>${language === "de" ? "MUSTER" : "PATTERN"}</small>${escapeHtml(input.slice(range.start, range.end))}</span>`;
      cursor = range.end;
    }
    html += escapeHtml(input.slice(cursor));
    return `<p class="lens-annotated-sentence">${html}</p>`;
  };

  const evidenceText = ({ hits, reasoningMatch }) => {
    const parts = [];
    if (hits.length) parts.push(locale === "ru" ? `структура: ${hits.length}` : `structure: ${hits.length} literal cue${hits.length === 1 ? "" : "s"}`);
    if (reasoningMatch) {
      const prefix = locale === "ru" ? "логика" : "reasoning";
      parts.push(`${prefix}: ${reasoningMatch.reasoning_move} · ${strengthLabel(reasoningMatch.strength)} · ${reasoningMatch.evidence}`);
    }
    return parts.join(" · ");
  };

  const render = async () => {
    const input = text.value.trim();
    if (!input) {
      results.innerHTML = "";
      annotation.innerHTML = "";
      empty.hidden = true;
      ready.hidden = false;
      return;
    }
    await loadPatterns();
    const matches = rank(input);
    ready.hidden = true;
    empty.hidden = matches.length > 0;
    annotation.innerHTML = highlight(input, matches[0]?.hits || []);
    results.innerHTML = matches.map(({ pattern, lang, hits, reasoningMatch, evidenceType, coverage }) => {
      const purpose = (reasoningMatch?.reasoning_move || pattern.reasoning_move) ? `<span>${escapeHtml(reasoningMatch?.reasoning_move || pattern.reasoning_move)}</span>` : "";
      const page = pattern.page_urls?.[locale] || `/${locale}/practice/`;
      const metric = reasoningMatch
        ? (locale === "ru" ? `${strengthLabel(reasoningMatch.strength)} логический сигнал` : `${strengthLabel(reasoningMatch.strength)} reasoning cue`)
        : (locale === "ru" ? `${Math.round(coverage * 100)}% покрытия структуры` : `${Math.round(coverage * 100)}% structure coverage`);
      return `<article class="lens-card" data-evidence-type="${escapeHtml(evidenceType)}"${reasoningMatch ? ` data-reasoning-strength="${escapeHtml(reasoningMatch.strength)}"` : ""}>
        <div class="lens-card-meta"><code>${escapeHtml(pattern.id)}</code>${purpose}<span>${escapeHtml(metric)}</span></div>
        <h3>${escapeHtml(lang.formula)}</h3>
        <p class="lens-example">${escapeHtml(lang.example)}</p>
        <p class="lens-translation">${escapeHtml(lang.translation || "")}</p>
        <p class="lens-evidence">${escapeHtml(evidenceText({ hits, reasoningMatch }))}</p>
        <div class="lens-card-foot"><span>${escapeHtml(evidenceType)}</span><a href="${escapeHtml(page)}">${locale === "ru" ? "Учить паттерн" : "Learn this pattern"} →</a></div>
      </article>`;
    }).join("");
  };

  const loadReasoningRules = async () => {
    try {
      const response = await fetch("/data/pattern-lens-rules.json");
      if (!response.ok) return;
      reasoningRules = await response.json();
    } catch {
      reasoningRules = null;
    }
  };

  languageButtons.forEach((button) => button.addEventListener("click", async () => {
    language = button.dataset.lensLanguage;
    languageButtons.forEach((item) => item.setAttribute("aria-pressed", String(item === button)));
    if (language === "de" && text.value.trim() === copy.placeholder.trim()) {
      await loadPatterns();
      const germanSample = patterns.flatMap((pattern) => pattern.langs.filter((item) => item.lang === "de").map((item) => item.example)).find(Boolean);
      if (germanSample) text.value = germanSample;
    }
    await render();
  }));

  sampleButtons.forEach((button) => button.addEventListener("click", async () => {
    language = "en";
    languageButtons.forEach((item) => item.setAttribute("aria-pressed", String(item.dataset.lensLanguage === "en")));
    text.value = button.dataset.lensSample;
    text.focus();
    await render();
  }));

  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    await render();
  });

  loadReasoningRules();
}
